import sys, time, random, urllib.request, urllib.parse, ssl

BASE = "https://ccmc.gsfc.nasa.gov"
UA = "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36"


def bad(b):
    return len(b) < 2000 and (b"Proxy Error" in b or b"SSL Handshake" in b or b"502 Bad" in b or b"503 Service" in b)


def fetch(url, data=None, tries=10, minsize=0, timeout=300):
    if url.startswith("/"):
        url = BASE + url
    body = None
    if data is not None:
        body = urllib.parse.urlencode(data, doseq=True).encode()
    last = None
    for k in range(tries):
        try:
            req = urllib.request.Request(url, data=body, headers={"User-Agent": UA})
            with urllib.request.urlopen(req, timeout=timeout) as r:
                b = r.read()
                ct = r.headers.get("Content-Type", "")
            if bad(b) or len(b) < minsize:
                last = f"bad response {len(b)} bytes"
            else:
                return b, ct
        except Exception as e:
            last = repr(e)
            if hasattr(e, "code") and e.code == 404:
                return None, "404"
        time.sleep(5 + random.random() * 15)
    sys.stderr.write(f"FAILED {url}: {last}\n")
    return None, last


if __name__ == "__main__":
    url, out = sys.argv[1], sys.argv[2]
    b, ct = fetch(url)
    if b is None:
        sys.exit(1)
    open(out, "wb").write(b)
    print(len(b), ct)
EOF
